head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > P > mergedCellVerticalAlign]<br/>동일값의 Cell 이 자동으로 병합될때 Cell 값의 수직 정렬 방식을 설정합니다.",
    "validation" : [
        "mergeCells, mergeCellsFixedCols, mergeCellsFixedRows 속성값이 'never' 가 아닌 영역에 적용됩니다.",
        "'top' 설정 시 병합된 Cell 영역의 상단에 Cell 값이 표시되며 'w2grid_vertical_align_top' CSS 클래스가 적용됩니다.",
        "'middle' 설정 시 병합된 Cell 영역의 중앙에 Cell 값이 표시되며, 병합된 Cell 이 짝수인 경우 Row 에 걸쳐서 Cell 값이 표시됩니다.",
        "'bottom' 설정 시 병합된 Cell 영역의 하단에 Cell 값이 표시되며 'w2grid_vertical_align_bottom' CSS 클래스가 적용됩니다.",
        "병합된 Cell 영역에만 적용되며 병합되지 않은 Cell 엔 적용되지 않습니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // con_ 설정값 수집 : '' 미설정(속성 제외=기본 동작) / top / middle / bottom
    let vAlign = con_mergedCellVerticalAlign.getValue();

    // 병합 옵션 구성
    //  - mergeCells="bycol" 고정 : 세로 병합이 항상 발생하도록 하여 수직 정렬 효과 확인
    //  - mergedCellVerticalAlign 미설정('') 이면 속성 자체를 추가하지 않음(기본 동작)
    let properties = {
        dataList: "data:dlt_bind",
        mergeCells: "bycol",
    };
    if (vAlign !== '') {
        properties.mergedCellVerticalAlign = vAlign;
    }

    let cList = $c.gcm.createCList(properties);

    // 현재 설정 상태 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="mergeCells=bycol(고정), mergedCellVerticalAlign=' + (vAlign === '' ? '(미설정)' : vAlign) + ' / col1=3행병합(홀수), col2=2행병합(짝수), col3=비병합(단일 셀)"', '', 'label1');

    // dataList 생성 후 병합이 보이도록 데이터 구성
    //   col1(A,A,A,B) : 행0~2 동일값 연속 → 3행 병합(홀수), middle 중앙 표시 확인
    //   col2(X,X,Y,Z) : 행0~1 동일값 연속 → 2행 병합(짝수), middle "Row 에 걸쳐서 표시" 확인
    //   col3(1,2,3,4) : 연속 동일값 없음 → 비병합(@spec : 클래스 미적용 확인)
    $c.gcm.createDynamicDataList('', '', 'dlt_bind');
    dlt_bind.setJSON([
        { "col1": "A", "col2": "X", "col3": "1" },
        { "col1": "A", "col2": "X", "col3": "2" },
        { "col1": "A", "col2": "Y", "col3": "3" },
        { "col1": "B", "col2": "Z", "col3": "4" }
    ], false);

    // target 생성
    let grp_comp = document.querySelector('.tc_group_basic');
    let strTarget = '';
    let strNameSpace = $c.gcm.getNameSpace();

    strTarget += '<w2:gridView ' + strNameSpace + ' ' + cList + ' checkAllType="false" id="" style="width:300px;height:240px;">';
    strTarget += '<w2:caption style="" id="caption1" value="mergedCellVerticalAlign sample"></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="row1">';
    strTarget += '<w2:column width="90" style="" inputType="text" id="column1" value="col1(3행병합)"></w2:column>';
    strTarget += '<w2:column width="90" style="" inputType="text" id="column2" value="col2(2행병합)"></w2:column>';
    strTarget += '<w2:column width="90" style="" inputType="text" id="column3" value="col3(비병합)"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="row2">';
    strTarget += '<w2:column width="90" style="" inputType="text" id="col1" value=""></w2:column>';
    strTarget += '<w2:column width="90" style="" inputType="text" id="col2" value=""></w2:column>';
    strTarget += '<w2:column width="90" style="" inputType="text" id="col3" value=""></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin["target1"] = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );
}



// 수직정렬 확인 : 병합 그룹별로 표시 텍스트가 위치한 td 와 적용된 CSS 클래스를 확인
//  - top    : 병합 영역 상단(첫 행) td 에 텍스트 + 'w2grid_vertical_align_top' 클래스
//  - bottom : 병합 영역 하단(마지막 행) td 에 텍스트 + 'w2grid_vertical_align_bottom' 클래스
//  - middle : 병합 영역 중앙 td 에 텍스트(짝수 병합이면 Row 에 걸쳐 표시), 클래스 미적용
//  - 미설정 : 기본 동작(상단 표시, 정렬 클래스 미적용)
//  - col3(비병합) : 정렬 클래스가 적용되지 않아야 함(@spec)
scwin.btn_checkAlign_onclick = function (e) {
    let bottom = wf_body_bottom.getObj("scwin");
    bottom.btn_clear_onclick();

    let optVal = target1.options.mergedCellVerticalAlign;
    bottom.setReturnValue("[옵션] mergedCellVerticalAlign : '" + optVal + "' (''=미설정→기본)");

    // colIndex 별로 표시 텍스트가 들어있는 td 와 정렬 클래스를 조사
    //  colIdByIndex : col1=0(3행병합), col2=1(2행병합), col3=2(비병합)
    let colIdByIndex = ["col1", "col2", "col3"];
    let alignClasses = ["w2grid_vertical_align_top", "w2grid_vertical_align_middle", "w2grid_vertical_align_bottom"];

    for (let c = 0; c < colIdByIndex.length; c++) {
        // 해당 컬럼의 모든 행 td 수집 (display:none 포함)
        let tds = [];
        for (let r = 0; r < 4; r++) {
            let td = document.querySelector("td[id*='target1_cell_" + r + "_" + c + "']");
            if (td) tds.push({ r: r, td: td });
        }
        if (tds.length === 0) continue;

        // 병합 앵커(rowSpan>1) 탐색
        let anchor = null;
        for (let i = 0; i < tds.length; i++) {
            if ((tds[i].td.rowSpan || 1) > 1) { anchor = tds[i]; break; }
        }

        if (!anchor) {
            // 비병합 컬럼(col3) : 정렬 클래스가 어떤 행 td 에도 없어야 함(@spec)
            let hasAnyAlignClass = false;
            for (let i = 0; i < tds.length; i++) {
                for (let a = 0; a < alignClasses.length; a++) {
                    if (tds[i].td.classList.contains(alignClasses[a])) hasAnyAlignClass = true;
                }
            }
            bottom.setReturnValue(colIdByIndex[c] + "(비병합) : 정렬클래스 적용 = " + hasAnyAlignClass + " (false 면 @spec 준수)");
            continue;
        }

        // 병합 그룹 정보 : 앵커 rowSpan = 병합 행 수
        let span = anchor.td.rowSpan;
        let mergedRows = [];
        for (let i = anchor.r; i < anchor.r + span; i++) mergedRows.push(i);

        // 적용된 정렬 클래스 (앵커/병합 영역 td 중 정렬 클래스를 가진 td)
        let appliedClass = "";
        for (let i = 0; i < tds.length; i++) {
            if (mergedRows.indexOf(tds[i].r) < 0) continue;
            for (let a = 0; a < alignClasses.length; a++) {
                if (tds[i].td.classList.contains(alignClasses[a])) appliedClass = alignClasses[a];
            }
        }

        // 표시 텍스트가 위치한 행(td) : display 되어 있고 textContent 가 비어있지 않은 td
        let textRows = [];
        for (let i = 0; i < tds.length; i++) {
            if (mergedRows.indexOf(tds[i].r) < 0) continue;
            let txt = (tds[i].td.textContent || "").trim();
            if (tds[i].td.style.display !== 'none' && txt !== "") textRows.push(tds[i].r);
        }

        bottom.setReturnValue(colIdByIndex[c] + " : " + span + "행병합(행" + mergedRows[0] + "~행" + mergedRows[mergedRows.length - 1] + ") / 표시행=[" + textRows.join(",") + "] / 적용클래스='" + (appliedClass || "(없음)") + "'");
    }
}
